SELECT COUNT(DISTINCT e.engage_member_pivot) as distinct_members, 
       COUNT(*) as total_engagement
FROM engagement e;

SELECT activity_reg, 
       REGEXP_REPLACE(content_consumption_rate, '[^0-9.]', '') as cci_raw
FROM interactions LIMIT 10;

SELECT activity_reg, 
       CAST(SUBSTRING(content_consumption_rate FROM '^[0-9.]+') AS numeric) as cci_raw
FROM interactions LIMIT 10;
